class Solution:
    def leftMostColumnWithOne(self, binaryMatrix) -> int:
        rows, cols = binaryMatrix.dimensions()
        row, col = 0, cols - 1
        result = -1
        while row < rows and col >= 0:
            if binaryMatrix.get(row, col) == 1:
                result = col
                col -= 1
            else:
                row += 1
        return result

